ruleBookInfo.init:
@js:(function() {
    var html = src;
    var book = {};

    // 辅助函数：根据元素ID提取并解码内容
    function getDecodedById(id) {
        var regex = new RegExp('document\\.getElementById\\("' + id + '"\\)\\.innerHTML = hashe256\\("([^"]+)"\\)');
        var match = html.match(regex);
        if (match) {
            return java.base64Decode(match[1]);
        }
        return "";
    }

    // 书名
    var titleMatch = html.match(/<h1 class="article-title"[^>]*>[\s\S]*?<script>[\s\S]*?hashe256\("([^"]+)"\)/);
    if (titleMatch) {
        book.book_name = java.base64Decode(titleMatch[1]);
    }

    // 封面（ThumbnailImg 内图片）
    var thumbMatch = html.match(/<div id="ThumbnailImg">[\s\S]*?hashe256\("([^"]+)"\)/);
    if (thumbMatch) {
        var imgHtml = java.base64Decode(thumbMatch[1]);
        var imgSrcMatch = imgHtml.match(/<img[^>]+src="([^"]+)"/);
        if (imgSrcMatch) {
            book.thumb = imgSrcMatch[1];
        }
    }

    // 作者
    var authorEnc = getDecodedById("Author");
    if (authorEnc) {
        book.author = authorEnc;
    }

    // 状态（连载中/完结）
    var statusEnc = getDecodedById("Status");
    if (statusEnc) {
        book.status = statusEnc;
    }

    // 类型（韩漫/日漫）
    var regionEnc = getDecodedById("Region");
    if (regionEnc) {
        book.category = regionEnc;
    }

    // 简介
    var descEnc = getDecodedById("Description");
    if (descEnc) {
        book.summary = descEnc;
    }

    // 将状态附加到简介前（可选）
    if (book.status && book.summary) {
        book.summary = "【" + book.status + "】\n" + book.summary;
    }

    // 处理封面相对路径
    if (book.thumb && book.thumb.startsWith("/")) {
        var baseUrl = java.get("baseUrl") || "";
        if (baseUrl) {
            book.thumb = baseUrl.replace(/\/$/, "") + book.thumb;
        }
    }

    return book;
})();

ruleContent.content:
@js:(function() {
    var html = src;

    // 提取 decodeBinaryString 中的二进制字符串
    var binMatch = html.match(/document\.getElementById\("imgs"\)\.innerHTML = decodeBinaryString\('([^']+)'\)/);
    if (!binMatch) {
        java.log("未找到二进制字符串");
        return "";
    }
    var binStr = binMatch[1];

    // 模拟 decodeBinaryString：将二进制字符串每8位转为一个字符，然后两次Base64解码
    function decodeBinaryString(binaryStr) {
        var result = "";
        for (var i = 0; i < binaryStr.length; i += 8) {
            var byte = binaryStr.substr(i, 8);
            result += String.fromCharCode(parseInt(byte, 2));
        }
        // 第一次Base64解码
        var firstDecode = java.base64Decode(result);
        // 第二次Base64解码
        var secondDecode = java.base64Decode(firstDecode);
        return secondDecode;
    }

    var imgHtml = decodeBinaryString(binStr);
    java.log("解码后的图片HTML:\n" + imgHtml);

    // 提取所有 <img> 标签的 src
    var imgRegex = /<img[^>]+src="([^"]+)"/g;
    var images = [];
    var match;
    while ((match = imgRegex.exec(imgHtml)) !== null) {
        images.push(match[1]);
    }

    if (images.length === 0) {
        return "";
    }

    // 返回拼接的图片HTML
    return images.map(function(url) {
        return '<img src="' + url + '">';
    }).join('\n');
})();

